"Вычисли удобным способом: 720 : (9 · 5) = ?": "قولاي ئۇسۇلدا ھېسابلا: 720 : (9 · 5) = ?",
"Вычисли объём в дм³: он равен числу литров.": "ھەجىمنى dm³ دا ھېسابلا: ئۇ لىتىر سانىغا تەڭ.",
"У куба 12 рёбер, все равны: 5 · 12 = 60 см.": "كۇبنىڭ 12 قىرى بار، ھەممىسى تەڭ: 5 · 12 = 60 cm.",
