"Найди корень уравнения 48 000 : x = 120 · 4.": "48 000 : x = 120 · 4 تەڭلىمىسىنىڭ يىلتىزىنى تاپ.",
"выражение, где последнее действие — сложение": "ئاخىرقى ئەمەل قوشۇش بولغان ئىپادە",
"Задумали число, увеличили на 8 и получили 30": "بىر سان ئويلاندى، ئۇ 8 گە ئاشۇرۇلدى ۋە 30 چىقتى",
"находим время: Путь 240 км, скорость 60 км/ч": "ۋاقىتنى تاپىمىز: يول 240 km، سۈرئەت 60 km/h",
"вместит меньше 50 л: 5 дм, 2 дм, 4 дм (40 л)": "50 l دىن ئاز سىغىدۇ: 5 dm، 2 dm، 4 dm (40 l)",
"Так определяется равносторонний треугольник.": "تەڭ تەرەپلىك ئۈچبۇلۇڭ مۇشۇنداق ئېنىقلىنىدۇ.",
"У многих фигур осей нет, например у буквы Р.": "نۇرغۇن شەكىللەرنىڭ ئوقى يوق، مەسىلەن Р ھەرپىنىڭ.",
"Урок 16. Длина ребра и объём параллелепипеда": "16-دەرس. پاراللېلېپىپېدنىڭ قىرىنىڭ ئۇزۇنلۇقى ۋە ھەجىمى",
"это решение: 12 для 9 < x < 15 (между 9 и 15)": "بۇ يېشىم: 9 < x < 15 ئۈچۈن 12 (9 بىلەن 15 نىڭ ئارىسىدا)",
"Реши уравнение 400 : x − 3 = 7. Чему равен x?": "400 : x − 3 = 7 تەڭلىمىسىنى يەچ. x نېمىگە تەڭ?",
